package render

const pageHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{.Spec.Title}}</title><style>
:root{color-scheme:light;--bg:#f5f6f8;--card:#fff;--ink:#17191c;--muted:#60656f;--line:#daddE3;--accent:#315efb;--accent2:#e9eeff;--danger:#a62d2d;font:16px/1.45 ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink)}main{width:min(100% - 24px,880px);margin:0 auto;padding:32px 0 96px}header{margin-bottom:24px}h1{font-size:clamp(1.75rem,6vw,2.6rem);line-height:1.1;margin:0 0 10px}h2,h3,h4,h5,h6{line-height:1.2;margin:0}.description,.help,.option-description{color:var(--muted)}.surface{display:grid;gap:16px}.component,.section{min-width:0}.field,.section,.comparison-wrap{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px}.section>.surface{margin-top:14px}.label{display:block;font-weight:650;margin-bottom:8px}.required::after{content:" *";color:var(--danger)}.help{font-size:.875rem;margin:7px 0 0}input,textarea,select,button{font:inherit}input[type=text],input[type=number],textarea,select{width:100%;min-height:48px;padding:10px 12px;border:1px solid #aeb3bc;border-radius:9px;background:#fff;color:inherit}textarea{min-height:112px;resize:vertical}input:focus,textarea:focus,select:focus,button:focus-visible{outline:3px solid color-mix(in srgb,var(--accent) 30%,transparent);outline-offset:2px}.choice{display:flex;gap:10px;align-items:flex-start;padding:11px 0}.choice input{width:22px;height:22px;flex:none}.choice+.choice{border-top:1px solid var(--line)}.choices{display:grid}.toggle input{appearance:none;width:46px;height:26px;border-radius:99px;background:#aeb3bc;position:relative;transition:.15s}.toggle input:before{content:"";position:absolute;width:20px;height:20px;left:3px;top:3px;border-radius:50%;background:white;transition:.15s}.toggle input:checked{background:var(--accent)}.toggle input:checked:before{transform:translateX(20px)}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(180px,100%),1fr));gap:12px}.gallery .choice{display:block;padding:0;border:1px solid var(--line);border-radius:12px;overflow:hidden;position:relative;background:var(--card)}.gallery img{display:block;width:100%;aspect-ratio:4/3;object-fit:cover;background:#eee}.gallery input{position:absolute;top:10px;right:10px}.gallery-copy{padding:12px}.image{max-width:100%;height:auto;border-radius:12px}.ranking{list-style:none;padding:0;margin:0;display:grid;gap:8px}.rank-item{display:flex;align-items:center;gap:10px;border:1px solid var(--line);border-radius:10px;padding:10px;background:#fff}.rank-handle{color:var(--muted);font-size:1.25rem}.rank-label{flex:1}.rank-buttons{display:flex;gap:4px}.rank-buttons button{width:40px;height:40px;border:1px solid var(--line);border-radius:8px;background:#fff}.approval{display:grid;grid-template-columns:1fr 1fr;gap:10px}.approval .choice{justify-content:center;border:1px solid var(--line);border-radius:10px;padding:14px}.comparison-wrap{overflow-x:auto}.comparison{border-collapse:collapse;width:100%;min-width:480px}.comparison th,.comparison td{text-align:left;padding:11px;border-bottom:1px solid var(--line)}.comparison th{font-weight:650}.actions{position:sticky;bottom:0;margin-top:20px;padding:12px;background:color-mix(in srgb,var(--bg) 90%,transparent);backdrop-filter:blur(8px);display:flex;gap:10px;align-items:center}.button{border:0;border-radius:10px;min-height:48px;padding:10px 18px;font-weight:650;background:var(--accent);color:white}.button.secondary{background:white;color:var(--ink);border:1px solid var(--line)}.save-status{font-size:.82rem;color:var(--muted);margin-left:auto}.density-compact .surface{gap:10px}.density-compact .field,.density-compact .section{padding:13px}.tone-playful{--accent:#7b3ff2;--accent2:#f1eaff}.tone-calm{--accent:#287a68;--accent2:#e3f2ed}[disabled]{opacity:.65;cursor:not-allowed}@media(max-width:520px){main{width:min(100% - 16px,880px);padding-top:20px}.field,.section,.comparison-wrap{padding:14px}.actions{margin-left:-8px;margin-right:-8px}.approval{grid-template-columns:1fr}}
</style></head><body class="{{.Classes}}"><main><header><h1>{{.Spec.Title}}</h1>{{if .Spec.Description}}<div class="description">{{.Spec.Description}}</div>{{end}}</header>
<form id="surface-form"><div class="surface">{{range .Spec.Components}}{{template "component" (dict . $.Result.Values $.ReadOnly)}}{{end}}</div>
{{if or .Spec.Actions.Submit .Spec.Actions.Reset}}<div class="actions">{{with .Spec.Actions.Submit}}<button class="button" id="submit" type="submit">{{if .Label}}{{.Label}}{{else}}Submit{{end}}</button>{{end}}{{with .Spec.Actions.Reset}}<button class="button secondary" id="reset" type="button">{{if .Label}}{{.Label}}{{else}}Reset{{end}}</button>{{end}}<span class="save-status" role="status" aria-live="polite" id="save-status"></span></div>{{end}}</form></main>
<script id="surface-config" type="application/json">{{.Initial}}</script><script>
(()=>{'use strict';const cfg=JSON.parse(document.getElementById('surface-config').textContent),form=document.getElementById('surface-form'),note=document.getElementById('save-status');let revision=cfg.revision,values=cfg.values||{},timer=null,queue=Promise.resolve();if(cfg.read_only){form.querySelectorAll('input,textarea,select,button').forEach(x=>x.disabled=true);note.textContent='Read only'}
const status=t=>{if(!cfg.read_only&&note)note.textContent=t};const set=(key,value)=>{values[key]=value;status('Unsaved');clearTimeout(timer);timer=setTimeout(()=>enqueue({[key]:value}),350)};
async function request(url,options){const r=await fetch(url,options);let body=null;try{body=await r.json()}catch(_){}if(!r.ok){const e=new Error('Request failed');e.response=r;e.body=body;throw e}return body}
function hydrate(next){values=next||{};form.querySelectorAll('[data-field]').forEach(el=>{const v=values[el.dataset.field];if(el.type==='checkbox')el.checked=el.dataset.array?Array.isArray(v)&&v.includes(el.value):v===true;else if(el.type==='radio')el.checked=v===el.value;else if(el.multiple)[...el.options].forEach(o=>o.selected=Array.isArray(v)&&v.includes(o.value));else el.value=v==null?'':v});document.querySelectorAll('[data-ranking]').forEach(list=>{const order=values[list.dataset.ranking];if(Array.isArray(order))order.forEach(v=>{const el=[...list.children].find(x=>x.dataset.value===v);if(el)list.appendChild(el)})})}
request(cfg.state_url).then(body=>{const result=body&&body.result||body;if(result&&Number.isInteger(result.revision)){revision=result.revision;hydrate(result.values)}if(body&&body.closed){form.querySelectorAll('input,textarea,select,button').forEach(x=>x.disabled=true);status('Read only')}}).catch(e=>{if(e.response&&e.response.status===410){form.querySelectorAll('input,textarea,select,button').forEach(x=>x.disabled=true);status('Expired')}});
function enqueue(dirty){queue=queue.then(()=>save(dirty)).catch(()=>status('Could not save'));return queue}
async function save(dirty){status('Saving…');try{const body=await request(cfg.state_url,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,values})});const result=body&&body.result||body;if(result&&Number.isInteger(result.revision))revision=result.revision;status('Saved')}catch(e){if(e.response&&e.response.status===409){const current=e.body&&e.body.result||e.body;if(current&&current.values&&Number.isInteger(current.revision)){values=Object.assign({},current.values,dirty);revision=current.revision;return save(dirty)}}throw e}}
form.addEventListener('input',e=>{const el=e.target,id=el.dataset.field;if(!id)return;if(el.tagName==='SELECT'&&el.multiple)return;if(el.type==='checkbox'){if(el.dataset.array){const picked=[...form.querySelectorAll('[data-field="'+CSS.escape(id)+'"][data-array]:checked')].map(x=>x.value);set(id,picked)}else set(id,el.checked)}else if(el.type==='number')set(id,el.value===''?null:Number(el.value));else set(id,el.value)});
form.addEventListener('change',e=>{if(e.target.tagName==='SELECT'&&e.target.multiple){set(e.target.dataset.field,[...e.target.selectedOptions].map(x=>x.value))}});
document.querySelectorAll('[data-ranking]').forEach(list=>{const sync=()=>set(list.dataset.ranking,[...list.querySelectorAll('[data-value]')].map(x=>x.dataset.value));list.addEventListener('click',e=>{const b=e.target.closest('button[data-move]');if(!b)return;const li=b.closest('li'),other=b.dataset.move==='up'?li.previousElementSibling:li.nextElementSibling;if(other){if(b.dataset.move==='up')list.insertBefore(li,other);else list.insertBefore(other,li);sync()}})});
form.addEventListener('submit',async e=>{e.preventDefault();document.querySelectorAll('[data-min-selections]').forEach(g=>{const count=g.querySelectorAll('input:checked,option:checked').length,min=Number(g.dataset.minSelections||0),max=Number(g.dataset.maxSelections||Infinity),input=g.querySelector('input,select');if(input)input.setCustomValidity(count<min||count>max?'Choose between '+min+' and '+max+' options.':'')});if(!form.reportValidity())return;await enqueue({});try{const body=await request(cfg.submit_url,{method:'POST'}),result=body&&body.result||body;if(result&&Number.isInteger(result.revision))revision=result.revision;status('Submitted')}catch(_){status('Could not submit')}});
const reset=document.getElementById('reset');if(reset)reset.addEventListener('click',async()=>{if(!confirm('Clear all responses?'))return;try{const body=await request(cfg.reset_url,{method:'POST'}),result=body&&body.result||body;values={};if(result&&Number.isInteger(result.revision))revision=result.revision;location.reload()}catch(_){status('Could not reset')}})
})();</script></body></html>

{{define "component"}}{{$c := index . 0}}{{$v := index . 1}}{{$ro := index . 2}}
{{if eq $c.Kind "heading"}}<h{{if $c.Level}}{{$c.Level}}{{else}}2{{end}} class="component">{{$c.Content}}</h{{if $c.Level}}{{$c.Level}}{{else}}2{{end}}>
{{else if eq $c.Kind "text"}}<div class="component">{{$c.Content}}</div>
{{else if eq $c.Kind "image"}}<figure class="component"><img class="image" src="{{if $c.Asset}}{{$c.Asset}}{{else}}{{$c.URL}}{{end}}" alt="{{$c.Alt}}">{{if $c.Content}}<figcaption class="help">{{$c.Content}}</figcaption>{{end}}</figure>
{{else if eq $c.Kind "link"}}<div class="component"><a href="{{$c.URL}}" rel="noopener noreferrer" target="_blank">{{if $c.Label}}{{$c.Label}}{{else}}{{$c.URL}}{{end}}</a></div>
{{else if eq $c.Kind "divider"}}<hr class="component">
{{else if eq $c.Kind "section"}}<section class="section">{{if $c.Label}}<h2>{{$c.Label}}</h2>{{end}}{{if $c.Help}}<p class="help">{{$c.Help}}</p>{{end}}<div class="surface">{{range $c.Components}}{{template "component" (dict . $v $ro)}}{{end}}</div></section>
{{else if eq $c.Kind "input_text"}}<div class="field"><label class="label{{if $c.Required}} required{{end}}" for="c-{{$c.ID}}">{{$c.Label}}</label><input id="c-{{$c.ID}}" data-field="{{$c.ID}}" type="text" value="{{str (value $v $c.ID)}}" placeholder="{{$c.Placeholder}}" {{if $c.Required}}required{{end}}{{with $c.MinLength}} minlength="{{.}}"{{end}}{{with $c.MaxLength}} maxlength="{{.}}"{{end}}>{{template "help" $c}}</div>
{{else if eq $c.Kind "textarea"}}<div class="field"><label class="label{{if $c.Required}} required{{end}}" for="c-{{$c.ID}}">{{$c.Label}}</label><textarea id="c-{{$c.ID}}" data-field="{{$c.ID}}" placeholder="{{$c.Placeholder}}" {{if $c.Required}}required{{end}}{{with $c.MinLength}} minlength="{{.}}"{{end}}{{with $c.MaxLength}} maxlength="{{.}}"{{end}}>{{str (value $v $c.ID)}}</textarea>{{template "help" $c}}</div>
{{else if eq $c.Kind "number"}}<div class="field"><label class="label{{if $c.Required}} required{{end}}" for="c-{{$c.ID}}">{{$c.Label}}</label><input id="c-{{$c.ID}}" data-field="{{$c.ID}}" type="number" value="{{str (value $v $c.ID)}}" placeholder="{{$c.Placeholder}}" {{if $c.Required}}required{{end}}{{with $c.Min}} min="{{.}}"{{end}}{{with $c.Max}} max="{{.}}"{{end}}{{with $c.Step}} step="{{.}}"{{end}}>{{template "help" $c}}</div>
{{else if or (eq $c.Kind "checkbox") (eq $c.Kind "toggle")}}<div class="field"><label class="choice {{if eq $c.Kind "toggle"}}toggle{{end}}"><input data-field="{{$c.ID}}" type="checkbox" {{if checked (value $v $c.ID)}}checked{{end}}><span><span class="label">{{$c.Label}}</span>{{if $c.Help}}<span class="help">{{$c.Help}}</span>{{end}}</span></label></div>
{{else if eq $c.Kind "select"}}<div class="field"><label class="label{{if $c.Required}} required{{end}}" for="c-{{$c.ID}}">{{$c.Label}}</label><select id="c-{{$c.ID}}" data-field="{{$c.ID}}" {{if $c.Required}}required{{end}}><option value="">Choose…</option>{{range $c.Options}}<option value="{{.Value}}" {{if eq .Value (str (value $v $c.ID))}}selected{{end}}>{{.Label}}</option>{{end}}</select>{{template "help" $c}}</div>
{{else if eq $c.Kind "multi_select"}}<div class="field" data-min-selections="{{if $c.MinSelections}}{{$c.MinSelections}}{{else}}0{{end}}" data-max-selections="{{if $c.MaxSelections}}{{$c.MaxSelections}}{{else}}999999{{end}}"><label class="label{{if $c.Required}} required{{end}}" for="c-{{$c.ID}}">{{$c.Label}}</label><select id="c-{{$c.ID}}" data-field="{{$c.ID}}" multiple size="{{len $c.Options}}" {{if $c.Required}}required{{end}}>{{range $c.Options}}<option value="{{.Value}}" {{if contains (value $v $c.ID) .Value}}selected{{end}}>{{.Label}}</option>{{end}}</select>{{template "help" $c}}</div>
{{else if eq $c.Kind "checklist"}}<fieldset class="field" data-min-selections="{{if $c.MinSelections}}{{$c.MinSelections}}{{else}}0{{end}}" data-max-selections="{{if $c.MaxSelections}}{{$c.MaxSelections}}{{else}}999999{{end}}"><legend class="label{{if $c.Required}} required{{end}}">{{$c.Label}}</legend><div class="choices">{{range $c.Items}}<label class="choice"><input data-field="{{$c.ID}}" data-array="true" type="checkbox" value="{{.Value}}" {{if contains (value $v $c.ID) .Value}}checked{{end}}><span>{{.Label}}{{if .Description}}<span class="option-description"> — {{.Description}}</span>{{end}}</span></label>{{end}}</div>{{template "help" $c}}</fieldset>
{{else if eq $c.Kind "gallery"}}<fieldset class="field" data-min-selections="{{if $c.MinSelections}}{{$c.MinSelections}}{{else}}0{{end}}" data-max-selections="{{if $c.MaxSelections}}{{$c.MaxSelections}}{{else}}999999{{end}}"><legend class="label{{if $c.Required}} required{{end}}">{{$c.Label}}</legend><div class="gallery">{{range $c.Items}}<label class="choice">{{if .Image}}<img src="{{.Image}}" alt="">{{end}}<input data-field="{{$c.ID}}" data-array="true" type="checkbox" value="{{.Value}}" {{if contains (value $v $c.ID) .Value}}checked{{end}}><span class="gallery-copy"><strong>{{.Label}}</strong>{{if .Description}}<span class="option-description">{{.Description}}</span>{{end}}</span></label>{{end}}</div>{{template "help" $c}}</fieldset>
{{else if eq $c.Kind "ranking"}}<fieldset class="field"><legend class="label">{{$c.Label}}</legend><ol class="ranking" data-ranking="{{$c.ID}}">{{range ranked $c.Items (value $v $c.ID)}}<li class="rank-item" data-value="{{.Value}}"><span class="rank-handle" aria-hidden="true">≡</span><span class="rank-label">{{.Label}}</span><span class="rank-buttons"><button type="button" data-move="up" aria-label="Move {{.Label}} up">↑</button><button type="button" data-move="down" aria-label="Move {{.Label}} down">↓</button></span></li>{{end}}</ol>{{template "help" $c}}</fieldset>
{{else if eq $c.Kind "approval"}}<fieldset class="field"><legend class="label{{if $c.Required}} required{{end}}">{{$c.Label}}</legend><div class="approval"><label class="choice"><input data-field="{{$c.ID}}" type="radio" name="{{$c.ID}}" value="approved" {{if eq "approved" (str (value $v $c.ID))}}checked{{end}} {{if $c.Required}}required{{end}}> Approve</label><label class="choice"><input data-field="{{$c.ID}}" type="radio" name="{{$c.ID}}" value="rejected" {{if eq "rejected" (str (value $v $c.ID))}}checked{{end}}> Reject</label></div>{{template "help" $c}}</fieldset>
{{else if eq $c.Kind "comparison"}}<section class="comparison-wrap"><h2>{{$c.Label}}</h2><table class="comparison"><thead><tr><th scope="col"></th>{{range $c.Columns}}<th scope="col">{{.Label}}</th>{{end}}</tr></thead><tbody>{{range $c.Rows}}{{$row := .}}<tr><th scope="row">{{.Label}}</th>{{range $c.Columns}}<td>{{index $row.Values .Key}}</td>{{end}}</tr>{{end}}</tbody></table>{{template "help" $c}}</section>{{end}}{{end}}
{{define "help"}}{{if .Help}}<p class="help">{{.Help}}</p>{{end}}{{end}}`
